INSERT INTO news (title, slug, summary, body, category, country_id, status, published_at) VALUES
('Lancement : le Togo ouvre la marche', 'lancement-le-togo-ouvre-la-marche', 'Le premier classement hebdomadaire couvre le Togo avec un Top 20. Le Bénin, le Ghana, la Côte d''Ivoire et le Sénégal suivent avec un Top 10.', 'Cauri Charts publie chaque mardi le classement de la semaine précédente, calculé du lundi au dimanche. Le Togo, pays pilote, a un Top 20. Les quatre autres pays démarrent avec un Top 10, qui passera à 20 quand les données seront assez nombreuses.', 'annonce', 1, 'published', '2026-09-22 09:00:00'),
('Artistes et labels : déclarez vos chiffres', 'artistes-et-labels-declarez-vos-chiffres', 'Spotify for Artists, Audiomack, Boomplay : une capture de votre espace artiste suffit. Chaque déclaration est vérifiée avant d''être comptée.', 'Certaines plateformes ne publient pas leurs chiffres. Le formulaire de déclaration permet d''envoyer une capture de votre espace artiste. Elle est vérifiée par l''équipe et comptée seulement si elle est recoupée par une donnée publique.', 'annonce', NULL, 'published', '2026-09-23 10:00:00'),
('La méthodologie est publique', 'la-methodologie-est-publique', 'Une écoute audio vaut un point, une vue d''un clip officiel un demi. Seule la progression de la semaine compte.', 'Toutes les règles de calcul sont publiées : sources, poids, règle de diversité, contrôles anti-fraude. Toute modification est annoncée au moins deux semaines avant d''entrer en vigueur.', 'classement', NULL, 'published', '2026-09-24 11:00:00'),
('Les titres suspects sont examinés avant publication', 'les-titres-suspects-sont-examines', 'Un pic d''écoutes inexpliqué bloque la publication tant qu''il n''a pas été vérifié. Les exclusions sont publiées avec leur motif.', NULL, 'classement', NULL, 'published', '2026-09-26 12:00:00'),
('Bientôt : un classement pour toute l''Afrique de l''Ouest', 'bientot-prime-chart-afrique-de-l-ouest', 'Après six à huit semaines de régularité, un classement régional additionnera les points gagnés dans chacun des cinq pays.', NULL, 'annonce', NULL, 'published', '2026-09-28 09:00:00');

SET FOREIGN_KEY_CHECKS = 1;
